contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public payable {
        require(amount > 0, "amount positive");

        address borrowToken = address(c.data().underlyingBorrowToken);

        uint256 userBalBefore = c.getUserView(address(this)).borrowATokenBalance;
        uint256 poolLiquidityBefore = c.data().underlyingBorrowToken.balanceOf(address(c.data().variablePool));

        bool reverted;
        try c.withdraw(WithdrawParams({token: borrowToken, amount: amount, to: address(this)})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 userBalAfter = c.getUserView(address(this)).borrowATokenBalance;
        uint256 poolLiquidityAfter = c.data().underlyingBorrowToken.balanceOf(address(c.data().variablePool));

        // Withdrawal is capped by the user's balance, so it never reverts and only decreases the user's balance.
        assert(!reverted);
        assert(userBalAfter <= userBalBefore);
        // The protocol must not spend more pool liquidity than it actually holds.
        assert(poolLiquidityAfter <= poolLiquidityBefore + userBalAfter);
    }

    receive() external payable {}
}

