contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 amount, VerifyParams calldata vp) public payable {
        // setup: ensure protocol is not paused (deployed fresh, but be safe)
        if (c.paused()) {
            c.unpause();
        }
        require(!c.paused());

        // snapshot pause state before deciding call
        bool pausedBefore = c.paused();

        require(address(this).balance >= amount);

        // deciding call: a pausable action (deposit)
        DepositParams memory dp;
        dp.token = address(c.data().underlyingBorrowToken);
        dp.amount = amount;
        dp.to = address(this);

        bool reverted;
        try c.deposit{value: amount}(dp) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool pausedAfter = c.paused();

        // General rule: for a pausable action, revert exactly when paused (before state must equal after regardless)
        assert((pausedBefore == pausedAfter) && (reverted == pausedBefore));
    }

    struct DepositParams {
        address token;
        uint256 amount;
        address to;
    }

    receive() external payable {}
}

